int minutesToRot(std::vector<std::vector<int>>& grid) {
    int rows = grid.size();
    int cols = grid[0].size();
    std::queue<std::pair<int, int>> queue;
    int fresh = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 2) {
                queue.push({r, c});
            } else if (grid[r][c] == 1) {
                fresh++;
            }
        }
    }
    const int steps[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    int minutes = 0;
    // Each lap is one minute: the oranges that rotted last minute spread.
    while (!queue.empty() && fresh > 0) {
        minutes++;
        for (std::size_t i = queue.size(); i > 0; i--) {
            auto [r, c] = queue.front();
            queue.pop();
            for (const auto& step : steps) {
                int nr = r + step[0];
                int nc = c + step[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {
                    grid[nr][nc] = 2;
                    fresh--;
                    queue.push({nr, nc});
                }
            }
        }
    }
    return fresh == 0 ? minutes : -1;
}

int main() {
    int rows, cols;
    std::cin >> rows >> cols;
    std::vector<std::vector<int>> grid(rows, std::vector<int>(cols));
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            std::cin >> grid[r][c];
        }
