	queue := [][2]int{}
	fresh := 0
	for r := range grid {
		for c := range grid[r] {
			if grid[r][c] == 2 {
				queue = append(queue, [2]int{r, c})
			} else if grid[r][c] == 1 {
				fresh++
			}
		}
	}
	steps := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	minutes := 0
	head := 0
	// Each lap is one minute: the oranges that rotted last minute spread.
	for head < len(queue) && fresh > 0 {
		minutes++
		for levelEnd := len(queue); head < levelEnd; head++ {
			cell := queue[head]
			for _, step := range steps {
				r, c := cell[0]+step[0], cell[1]+step[1]
				if r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == 1 {
					grid[r][c] = 2
					fresh--
