import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function minutesToRot(grid: number[][]): number {
  const queue: [number, number][] = [];
  let fresh = 0;
  for (const [r, line] of grid.entries()) {
    for (const [c, cell] of line.entries()) {
      if (cell === 2) {
        queue.push([r, c]);
      } else if (cell === 1) {
        fresh++;
      }
    }
  }
  const steps: [number, number][] = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let head = 0;
  let minutes = 0;
  // Each lap is one minute: the oranges that rotted last minute spread.
  while (head < queue.length && fresh > 0) {
    minutes++;
    const levelEnd = queue.length;
    while (head < levelEnd) {
      const cell = queue[head++];
      if (cell === undefined) {
        break;
      }
      const [r, c] = cell;
      for (const [dr, dc] of steps) {
        // Off the grid, the lookups give undefined, which isn't a fresh orange.
        const line = grid[r + dr];
        if (line !== undefined && line[c + dc] === 1) {
          line[c + dc] = 2;
          fresh--;
          queue.push([r + dr, c + dc]);
        }
      }
    }
  }
  return fresh === 0 ? minutes : -1;
}

const numbers = input.trim().split(/\s+/).map(Number);
let pos = 0;
const next = (): number => numbers[pos++] ?? 0;
const rows = next();
const cols = next();
const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => next()));
console.log(minutesToRot(grid));
